// Werte werden als ein base64-kodierter JSON-Block an die Datenbank uebergeben.
// Grund: Die kommagetrennte Parameterliste des Postgres-Knotens zerlegt Texte mit Kommas
// und macht aus leeren Werten den Text "null" (Smoke-Test 10.09.2026, Ausfuehrung 21865).
const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const AKTEURE = ["jarvis", "rolf", "mitarbeiter", "externer"];
function b64(o) {
  const s = JSON.stringify(o);
  return (typeof Buffer !== "undefined") ? Buffer.from(s, "utf8").toString("base64") : btoa(unescape(encodeURIComponent(s)));
}
const ergebnis = [];
for (const item of $input.all()) {
  const kontext = item.json.context_id;
  if (KONTEXTE.indexOf(kontext) === -1) {
    throw new Error("fach_log_write_invalid_input: context_id nicht im Register");
  }
  if (!item.json.entry_kind) {
    throw new Error("fach_log_write_invalid_input: entry_kind fehlt");
  }
  if (AKTEURE.indexOf(item.json.actor) === -1) {
    throw new Error("fach_log_write_invalid_input: actor unzulaessig");
  }
  const zusammenfassung = String(item.json.summary_de || "");
  if (zusammenfassung.length < 3) {
    throw new Error("fach_log_write_invalid_input: summary_de fehlt oder ist zu kurz");
  }
  const zeile = {
    entry_kind: String(item.json.entry_kind),
    actor: item.json.actor,
    summary_de: zusammenfassung,
    action_id: item.json.action_id || null,
    task_id: item.json.task_id || null,
    event_id: item.json.event_id || null,
    corrects_log_id: item.json.corrects_log_id || null,
    body: item.json.body || {}
  };
  ergebnis.push({ json: {
    context_id: kontext,
    entry_kind: zeile.entry_kind,
    action_id: zeile.action_id,
    trace_id: item.json.trace_id || null,
    row_b64: b64(zeile)
  } });
}
return ergebnis;
